
import 'package:flutter/material.dart';

// ADDED: Firebase initialization
import 'package:firebase_core/firebase_core.dart';

// ADDED: Firebase configuration generated by FlutterFire CLI
import 'firebase_options.dart';

import 'theme/app_theme.dart';
import 'screens/login_screen.dart';
import 'screens/main_shell.dart';
import 'screens/program_details_screen.dart';

// ADDED: Admin dashboard screen imports
import 'screens/admin/admin_dashboard_screen.dart';
import 'screens/admin/admin_courses_screen.dart';
import 'screens/admin/admin_learners_screen.dart';
import 'screens/admin/admin_feedback_screen.dart';

// CHANGED: Made main() asynchronous to initialize Firebase before the app starts
Future<void> main() async {
  // ADDED: Ensures Flutter is initialized before Firebase
  WidgetsFlutterBinding.ensureInitialized();

  // ADDED: Initializes Firebase using your project configuration
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );

  runApp(const SkillBytesApp());
}

class SkillBytesApp extends StatelessWidget {
  const SkillBytesApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'SkillBytes',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.lightTheme,
      darkTheme: AppTheme.darkTheme,
      themeMode: ThemeMode.system,
      initialRoute: '/',

      onGenerateRoute: (settings) {
        final name = settings.name ?? '/';

        // EXISTING: Course details route preserved
        // Handles /course/:id
        if (name.startsWith('/course/')) {
          final id = name.substring('/course/'.length);

          return MaterialPageRoute(
            builder: (_) => ProgramDetailsScreen(courseId: id),
          );
        }

        switch (name) {
          // ADDED: Admin dashboard route
          case '/admin':
            return MaterialPageRoute(
              builder: (_) => const AdminDashboardScreen(),
            );

          // ADDED: Admin courses route
          case '/admin/courses':
            return MaterialPageRoute(
              builder: (_) => const AdminCoursesScreen(),
            );

          // ADDED: Admin learners route
          case '/admin/learners':
            return MaterialPageRoute(
              builder: (_) => const AdminLearnersScreen(),
            );

          // ADDED: Admin feedback route
          case '/admin/feedback':
            return MaterialPageRoute(
              builder: (_) => const AdminFeedbackScreen(),
            );

          // EXISTING: Login route preserved
          case '/':
            return MaterialPageRoute(
              builder: (_) => const LoginScreen(),
            );

          // EXISTING: Learner home route preserved
          case '/home':
            return MaterialPageRoute(
              builder: (_) => const MainShell(initialIndex: 0),
            );

          // EXISTING: Default route preserved
          default:
            return MaterialPageRoute(
              builder: (_) => const LoginScreen(),
            );
        }
      },
    );
  }
}
